package com.bananalab.lite;
import android.content.*;import java.io.*;import java.util.*;import org.json.*;
final class DeepChatTraining{
 static String train(Context c)throws Exception{String revision=ModelDepot.revision(c,"chat");BananaTransformer m=NeuralTraining.chat(c);JSONArray train=NeuralTraining.data(c,"train"),eval=NeuralTraining.data(c,"eval"),controls=NeuralTraining.defaultRows("anchor");Set<String> seen=new HashSet<>();for(int i=0;i<train.length();i++)seen.add(ChatLanguage.normalize(train.getJSONObject(i).getString("question")));for(int i=0;i<eval.length();i++)if(seen.contains(ChatLanguage.normalize(eval.getJSONObject(i).getString("question"))))throw new IllegalArgumentException("Preguntas compartidas entre entrenamiento y evaluación");float[][] baseline=TransformerTraining.snapshot(m);List<HeadTrainer.Token> anchor=NeuralTraining.tokens(m,controls);float[][] expected=HeadTrainer.distributions(anchor,m.head,m.headBias);double before=TransformerTraining.evaluate(m,eval);JavaChat.phase("Chat: retropropagación completa por embeddings, atención y bloques Transformer…");TransformerTraining.train(m,train,controls);double after=TransformerTraining.evaluate(m,eval),kl=HeadTrainer.divergence(NeuralTraining.tokens(m,controls),expected,m.head,m.headBias),delta=TransformerTraining.distance(m,baseline);boolean accepted=after<before-1e-5&&kl<=.003&&delta>0;JSONObject report=new JSONObject().put("kind","chat").put("method","Full causal Transformer reverse-mode backpropagation").put("fullTransformer",true).put("before",before).put("after",after).put("anchorKL",kl).put("weightDeltaL2",delta).put("accepted",accepted).put("epochs",2).put("trainExamples",train.length()).put("evalExamples",eval.length()).put("metric","mean_sequence_teacher_forced_NLL");ModelDepot.prefs(c).edit().putString("chatReport",report.toString()).commit();if(accepted){ByteArrayOutputStream bytes=new ByteArrayOutputStream();m.save(bytes);File file=ModelDepot.save(c,"chat",bytes.toByteArray());try(InputStream in=new FileInputStream(file)){BananaTransformer loaded=new BananaTransformer(in,c.getAssets().open("chat34/vocab.txt"),c.getAssets().open("chat34/tokenizer.json"));if(Math.abs(TransformerTraining.evaluate(loaded,eval)-after)>1e-6)throw new IOException("El checkpoint completo no reproduce la evaluación");}ModelDepot.publish(c,"chat",file,report,revision);}return (accepted?"Entrené y activé el Transformer completo de Banana Chat.":"Entrené un candidato completo y conservé el modelo activo: no pasó los controles.")+"\n"+report.toString(2)+"\nIncluye embeddings, posiciones, atención, capas internas y salida. Los datos son pocos y propios: no demuestra comprensión general, calidad equivalente a ChatGPT ni mejora garantizada en todos los temas.";}
}
